 void UpdateLanModeFields(bool updateNotice=true){if(lanModePicker==null)return;bool arena=ArenaModeSelected()||SealedModeSelected();bool ai=HumanAiSelected();if(lanNetworkFields!=null)lanNetworkFields.Visibility=ai?Visibility.Collapsed:Visibility.Visible;if(lanAgentField!=null)lanAgentField.Visibility=ai?Visibility.Visible:Visibility.Collapsed;if(aiStartButton!=null)aiStartButton.Visibility=ai?Visibility.Visible:Visibility.Collapsed;if(hostButton!=null)hostButton.Visibility=ai?Visibility.Collapsed:Visibility.Visible;if(joinButton!=null)joinButton.Visibility=ai?Visibility.Collapsed:Visibility.Visible;if(leaveButton!=null)leaveButton.Visibility=ai?Visibility.Collapsed:Visibility.Visible;if(lanClassField!=null)lanClassField.Visibility=arena?Visibility.Collapsed:Visibility.Visible;if(lanDeckField!=null)lanDeckField.Visibility=arena?Visibility.Collapsed:Visibility.Visible;bool busy=lanPeer!=null;lanClass.IsEnabled=lanDeck.IsEnabled=!busy&&!arena;if(localOpponentMode!=null)localOpponentMode.IsEnabled=!busy;if(aiStartButton!=null)aiStartButton.IsEnabled=!busy;if(updateNotice&&!busy&&lanNotice!=null&&arenaStage!=null&&arenaStage.Visibility!=Visibility.Visible)lanNotice.Text=ai?"选择完整30张卡组与人机对手，按正常规则开局。":arena?SealedModeSelected()?"现开赛：联机后选职业，开18包，组30张卡组，三局两胜，局间可重组。":"竞技模式：使用当前开放卡池，双方选职业后各进行30轮三选一，再进行三局两胜。":"双方连接同一局域网，各自选职业和卡组。一人创建房间，另一人填房主地址后加入。";}
 void BuildArenaStage(){
  arenaStage=new Grid{Visibility=Visibility.Collapsed};arenaStage.RowDefinitions.Add(new RowDefinition{Height=new GridLength(24)});arenaStage.RowDefinitions.Add(new RowDefinition{Height=new GridLength(28)});arenaStage.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});
  arenaStageTitle=T("竞技模式",11,Ink);arenaStageTitle.TextWrapping=TextWrapping.Wrap;arenaStage.Children.Add(arenaStageTitle);arenaStageProgress=T("",9,Muted);Grid.SetRow(arenaStageProgress,1);arenaStage.Children.Add(arenaStageProgress);arenaDraftContent=new Grid();arenaDraftContent.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(2,GridUnitType.Star)});arenaDraftContent.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});arenaOfferGrid=new Grid();for(int i=0;i<3;i++)arenaOfferGrid.ColumnDefinitions.Add(new ColumnDefinition());arenaOfferButtons=new Button[3];for(int i=0;i<3;i++){int index=i;var content=new StackPanel();var name=T("",10,Ink);name.TextAlignment=TextAlignment.Center;name.TextWrapping=TextWrapping.Wrap;content.Children.Add(name);var detail=T("",8,Muted);detail.TextAlignment=TextAlignment.Center;detail.TextWrapping=TextWrapping.Wrap;content.Children.Add(detail);var button=Btn("",24);button.ClickMode=System.Windows.Controls.ClickMode.Press;button.Content=new ScrollViewer{Focusable=false,Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};button.Width=Double.NaN;button.HorizontalAlignment=HorizontalAlignment.Stretch;button.Height=Double.NaN;button.VerticalAlignment=VerticalAlignment.Stretch;button.Margin=new Thickness(i==0?0:3,1,i==2?0:3,0);button.Padding=new Thickness(3);button.Click+=(s,e)=>PickArenaChoice(index);button.IsEnabled=false;Grid.SetColumn(button,i);arenaOfferGrid.Children.Add(button);arenaOfferButtons[i]=button;}arenaDraftContent.Children.Add(arenaOfferGrid);Grid.SetColumn(arenaOfferGrid,0);arenaPickedTitle=T("已选卡牌 · 0 / 30",9,Ink);arenaPickedRows=new Grid();var pickedBody=new Grid();pickedBody.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});pickedBody.RowDefinitions.Add(new RowDefinition());pickedBody.Children.Add(arenaPickedTitle);var pickedScroll=new ScrollViewer{Content=arenaPickedRows,VerticalScrollBar