 void StartArenaDraft(string opponentName,EffectLevel opponentEffects){lanGuestName=PlayerNames.Normalize(opponentName,1);lanGuestEffects=opponentEffects;lanArenaDraft=new ArenaDraftSession(catalog,Environment.TickCount,matchRules.Supports);lanSession=lanArenaDraft.Session;lanArenaView=lanArenaDraft.View(0);lanArenaWins0=lanArenaWins1=0;lanArenaGameNumber=0;lanArenaSeriesWinner=-2;lanNotice.Visibility=Visibility.Collapsed;UpdateArenaDraftUi(lanArenaView);PublishArenaDraftToGuest();status.Text="竞技模式 · 选择职业与卡牌";}
 void PublishArenaDraftToGuest(){if(lanPeer==null||lanArenaDraft==null)return;var message=new LanMessage{Kind="arena-draft",ArenaDraft=lanArenaDraft.View(1)};if(!lanPeer.Send(message))DisconnectLan("竞技选牌状态发送失败。");}
 void UpdateArenaDraftUi(ArenaDraftView view){if(view==null||arenaStage==null)return;SetArenaDraftLayout(true);arenaDraftContent.MaxHeight=minimal?100:250;lanNotice.Visibility=Visibility.Collapsed;arenaStage.Visibility=Visibility.Visible;string[] options=view.Choices??new string[0];if(view.Phase=="class")arenaStageTitle.Text="选择职业 · 从随机的 3 个职业中选 1 个";else if(view.Phase=="cards")arenaStageTitle.Text="竞技组牌 · "+ArenaClassLabel(view.ClassId)+" · 第 "+(view.Picks+1)+" / 30 次选择";else arenaStageTitle.Text="已完成 30 张竞技卡组，等待对手";arenaStageProgress.Text="你的进度 "+view.Picks+" / 30 · 对手 "+view.OpponentPicks+" / 30"+(view.OpponentComplete?" · 对手已完成":"");bool showPicked=view.Phase!="class";arenaPickedPanel.Visibility=showPicked?Visibility.Visible:Visibility.Collapsed;Grid.SetColumnSpan(arenaOfferGrid,showPicked?1:2);UpdateArenaPickedCards(view);for(int i=0;i<arenaOfferButtons.Length;i++){var button=arenaOfferButtons[i];if(i>=options.Length){button.Visibility=Visibility.Collapsed;button.IsEnabled=false;continue;}button.Visibility=Visibility.Visible;button.IsEnabled=!lanWaiting&&!view.Complete;var content=(StackPanel)((ScrollViewer)button.Content).Content;var name=(TextBlock)content.Children[0];var detail=(TextBlock)content.Children[1];if(view.Phase=="class"){name.Text=ArenaClassLabel(options[i]);detail.Text="选择该职业";button.ToolTip=name.Text;}else{var card=catalog.Card(options[i]);name.Text=card.Cost+" 费 · "+card.Name;detail.Text=(card.Type=="MINION"?card.Attack+"/"+card.Health+" 随从":card.Type=="WEAPON"?"武器 "+card.Attack+"/"+card.Durability:"法术")+"\n"+(card.Text.Length>0?card.Text:"无特殊效果");button.ToolTip=card.Name+" · "+card.Text;}}status.Text=lanWaiting?"选项已提交，等待服务器确认。":view.Complete?"竞技组牌完成，等待对手。":"竞技模式 · "+(view.Phase=="class"?"选择职业":"选择卡牌");}
void UpdateArenaPickedCards(ArenaDraftView view){if(arenaPickedRows==null||view==null)return;arenaPickedRows.Children.Clear();arenaPickedRows.RowDefinitions.Clear();string[] picked=view.PickedCards??new string[0];arenaPickedTitle.Text="已选卡牌 · "+picked.Length+" / 30";var grouped=picked.GroupBy(id=>id).Select(group=>new{Card=catalog.Card(group.Key),Count=group.Count()}).OrderBy(item=>item.Card.Cost).ThenBy(item=>item.Card.Name,StringComparer.CurrentCulture).ToArray();foreach(var item in grouped){var row=T(item.Card.Cost+"费 · "+item.Card.Name+(item.Count>1?" ×"+item.Count:""),9,Ink);row.Tag=item.Card.Cost;row.TextTrimming=TextTrimming.CharacterEllipsis;row.ToolTip=item.Card.Name+(item.Count>1?" ×"+item.Count:"");row.Margin=new Thickness(0,1,0,1);arenaPickedRows.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});Grid.SetRow(row,arenaPickedRows.RowDefinitions.Count-1);arenaPickedRows.Children.Add(row);}}
 string ArenaClassLabel(string id){var item=Classes.FirstOrDefault(c=>c.Key==id);return item==null?id:item.Label;}
 void PickArenaChoice(int index){if(!lanArenaMode||lanArenaView==null||lanWaiting||lanArenaView.Complete)return;if(index<0||index>2||index>=(lanArenaView.Choices==null?0:lanArenaView.Choices.Length))return;if(lanIsHost){try{lanArenaDraft.Pick(0,lanArenaView.Session,lanArenaView.Revision,index);lanArenaView=lanArenaDraft.View(0);UpdateArenaDraftUi(lanArenaView);if(lanArenaDraft.View(0).Complete&&lanArenaDraft.View(1).Complete){StartArenaMatch();return;}PublishArenaDraftToGuest();}catch(InvalidOperationException ex){status.Text=ex.Message;}}else{lanPendingArenaRevision=lanArenaView.Revision;lanWaiting=true;UpdateArenaDraftUi(lanArenaView);if(lanPeer==null||!lanPeer.Send(new LanMessage{Kind="arena-pick",ArenaSession=lanArenaView.Session,ArenaRevision=lanArenaView.Revision,ChoiceIndex=index})){DisconnectLan("发送竞技选择失败。");}}}
 void StartArenaMatch(){if(lanArenaDraft==null||!lanArenaDraft.View(0).Complete||!lanArenaDraft.View(1).Complete)return;var host=lanArenaDraft.Deck(0);var guest=lanArenaDraft.Deck(1);int? startingSeat=null;
#if VERIFY
  startingSeat=VerificationRun.FirstSeat;
#endif
  lanAuthority=new LanHostGame(catalog,host,guest,Environment.TickCount,startingSeat,lanChosenName,lanGuestName,GameModes.Arena);lanAuthority.SetPresentation(0,CurrentEffects);lanAuthority.SetPresentation(1,lanGuestEffects);match=lanAuthority.Game;lanSession=lanAuthority.Session;lanRevision=0;lanReady=true;lanWaiting=false;matchViewSeat=0;awaitHandoff=false;ClearPending();inspectMatch=false;matchHandScroll=0;lanArenaGameNumber=lanAuthority.ArenaGameNumber;lanArenaWins0=lanArenaWins1=0;lanArenaSeriesWinner=-2;lanArenaView=null;SetArenaDraftLayout(false);arenaStage.Visibility=Visibility.Collapsed;lanNotice.Visibility=Visibility.Visible;PublishLan();RenderMatch();ShowPage("match");status.Text="竞技模式 · 卡组完成，进行三局两胜";}
 string ArenaSeriesLabel(){if(!lanArenaMode)return null;if(lanAuthority!=null)return lanAuthority.ArenaScoreLabel();string end=lanArenaSeriesWinner==-2?" · 第 "+lanArenaGameNumber+" 局":lanArenaSeriesWinner==-1?" · 系列赛平局":" · 系列赛结束";return lanArenaWins0+" - "+lanArenaWins1+end;}
